function safeUrl(value){if(typeof value!=='string'||!value.trim())return '';try{const parsed=new URL(value);return parsed.protocol==='https:'?parsed.href:'';}catch(_error){return '';}}
function element(tag,text,className){const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=String(text);return node;}
function dash(){return element('span','—','mb-essential__dash');}
function segment(active){return active?element('span','✓','mb-essential__segment'):dash();}
function resource(source,lang,type,label,product){const raw=type==='quotation'?source:(source&&source[lang]);const url=safeUrl(raw);if(!url)return dash();const link=document.createElement('a');link.className='mb-essential__resource mb-essential__resource--'+type;link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.setAttribute('aria-label',label+': '+product);link.innerHTML=ICONS[type];return link;}
function appendCell(row,content,className){const cell=document.createElement('td');if(className)cell.className=className;cell.appendChild(content);row.appendChild(cell);}
function render(lang,t){const tbody=document.getElementById('essentialSystemsRows');tbody.replaceChildren();const empty=document.getElementById('emptyState');if(!PRODUCTS.length){empty.hidden=false;empty.textContent=t.no_products;return;}empty.hidden=true;const counts=PRODUCTS.reduce(function(acc,item){acc[item.category]=(acc[item.category]||0)+1;return acc;},{});const categoryRendered={};PRODUCTS.forEach(function(item){const row=document.createElement('tr');if(!categoryRendered[item.category]){const categoryCell=document.createElement('td');categoryCell.className='mb-essential__category';categoryCell.rowSpan=counts[item.category];categoryCell.appendChild(element('span',t[item.category]||item.category,'mb-essential__category-badge'));row.appendChild(categoryCell);categoryRendered[item.category]=true;}appendCell(row,element('span',item.product,'mb-essential__product'));appendCell(row,segment(Boolean(item.segments[0])),'mb-essential__center');appendCell(row,segment(Boolean(item.segments[1])),'mb-essential__center');appendCell(row,segment(Boolean(item.segments[2])),'mb-essential__center');appendCell(row,element('span',item.setup[lang]||item.setup.en),'mb-essential__center');appendCell(row,element('span',t[item.area]||item.area,'mb-essential__area'),'mb-essential__center');appendCell(row,resource(item.quotation,lang,'quotation',t.open_quotation_checklist,item.product),'mb-essential__center');appendCell(row,resource(item.brochure,lang,'brochure',t.open_brochure,item.product),'mb-essential__center');appendCell(row,resource(item.presentation,lang,'presentation',t.open_presentation,item.product),'mb-essential__center');appendCell(row,resource(item.video,lang,'video',t.open_video,item.product),'mb-essential__center');appendCell(row,resource(item.demo,lang,'demo',t.open_demo,item.product),'mb-essential__center');appendCell(row,resource(item.website,lang,'website',t.open_website,item.product),'mb-essential__center');tbody.appendChild(row);});}
function setText(id,value){const node=document.getElementById(id);if(node)node.textContent=value;}
function init(){const lang=language();const t=translated(lang);const corporateTitle=CORPORATE_TITLES[lang]||CORPORATE_TITLES.en;document.documentElement.lang=lang;document.title=corporateTitle;setText('pageTitle',corporateTitle);setText('pageSubtitle',t.page_subtitle);setText('thCategory',t.category);setText('thProduct',t.product);setText('thSegment',t.segment);setText('thBusiness',SEGMENT_TITLES.businessEngine);setText('thEnterprise',SEGMENT_TITLES.enterpriseMachine);setText('thCorporate',SEGMENT_TITLES.corporateSystem);setText('thSetup',t.setup_time);setText('thArea',t.functional_area);setText('thQuotation',t.quotation_checklist);setText('thBrochure',t.brochure);setText('thPresentation',t.presentation);setText('thVideo',t.video);setText('thDemo',t.demo);setText('thWebsite',t.website);setText('versionLabel',t.version);render(lang,t);}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init,{once:true});}else{init();}
})();
